<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Global Chat</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="page"><header class="simple-top"><a href="dashboard.php">← Dashboard</a><div class="balance">Balance: <strong id="balanceText">KES 0</strong></div></header><section class="chat-layout"><aside class="chat-list" id="chatList"></aside><main class="chat-box"><div class="chat-head"><h2 id="chatName">Select a chat</h2><small>Auto-generated chat responses</small></div><div class="messages" id="messages"><p class="empty">Choose a profile to start chatting.</p></div><form id="chatForm" class="chat-form"><input id="chatInput" placeholder="Type your message..." required><button>Send</button></form></main></section></div><script src="assets/app.js"></script><script>const profiles=[['Anna','Germany'],['Sofia','Spain'],['Emma','France'],['Lina','Sweden'],['Marta','Italy'],['Eva','Netherlands'],['Clara','Belgium'],['Nora','Norway'],['Helena','Portugal'],['Laura','Austria']];const replies=['That sounds interesting. Tell me more.','I like meeting people from different places.','What do you enjoy doing during your free time?','That is nice. I hope your day is going well.'];let active=null,replyIndex=0;const chatList=document.getElementById('chatList');const messages=document.getElementById('messages');profiles.forEach(p=>{const btn=document.createElement('button');btn.innerHTML=`<strong>${p[0]}</strong><span>${p[1]}</span>`;btn.onclick=()=>{active=p;replyIndex=0;document.getElementById('chatName').textContent=p[0]+' • '+p[1];messages.innerHTML='';addMsg('bot','Hi, nice to meet you.');};chatList.appendChild(btn);});function addMsg(type,text){const d=document.createElement('div');d.className='msg '+type;d.textContent=text;messages.appendChild(d);messages.scrollTop=messages.scrollHeight;}document.getElementById('chatForm').addEventListener('submit',e=>{e.preventDefault();if(!active)return alert('Select a chat first.');const input=document.getElementById('chatInput');addMsg('user',input.value);input.value='';if(replyIndex<4)setTimeout(()=>addMsg('bot',replies[replyIndex++]),700);});</script></body></html>